CREATE TABLE IF NOT EXISTS users(id SERIAL PRIMARY KEY,name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,password_hash TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'user' CHECK(role IN ('user','admin')),created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS plans(id SERIAL PRIMARY KEY,name TEXT NOT NULL,description TEXT DEFAULT '',price_cents INT NOT NULL CHECK(price_cents>=0),currency TEXT DEFAULT 'usd',billing_interval TEXT DEFAULT 'month' CHECK(billing_interval IN ('month','year')),features JSONB DEFAULT '[]',active BOOLEAN DEFAULT TRUE);
CREATE TABLE IF NOT EXISTS subscriptions(id SERIAL PRIMARY KEY,user_id INT REFERENCES users(id) ON DELETE CASCADE,plan_id INT REFERENCES plans(id),stripe_subscription_id TEXT UNIQUE,status TEXT DEFAULT 'incomplete',current_period_end TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS invoices(id SERIAL PRIMARY KEY,user_id INT REFERENCES users(id) ON DELETE CASCADE,stripe_invoice_id TEXT UNIQUE,amount_paid INT DEFAULT 0,currency TEXT DEFAULT 'usd',status TEXT,invoice_url TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS usage_events(id SERIAL PRIMARY KEY,user_id INT REFERENCES users(id) ON DELETE CASCADE,event_name TEXT NOT NULL,quantity INT DEFAULT 1,created_at TIMESTAMPTZ DEFAULT NOW());
